  // but falls back to the whole envelope for empty content / errors.
  if (contentType.includes("application/json") || looksLikeEnvelope(buf)) {
    let envelope;
    try { envelope = JSON.parse(buf.toString("utf8")); }
    catch { throw new Error(`...unparseable...`); }
    if (envelope.code !== 0) throw new Error(envelope.message ?? `...`);
