    // this is the empty-content case. A zero-byte resource is legitimate.
    const { content = "", encoding = "utf-8" } = envelope.data ?? {};
    if (typeof content !== "string") throw new Error(...);
    return Buffer.from(content, encoding === "base64" ? "base64" : "utf8");
  }
  return buf;
}
```

