/**
 * Fetch one resource file from a team skill's bridge, as raw bytes.
 *
 * Team experience (skill `eval-skill-resource-download`, tracking value
 * bt-pu6nyfhmu2v): the bridge's `files/read` subpath always answers with a JSON
 * envelope, so saving its body to disk writes a JSON document, not the file.
 * The subpath that returns the resource's bytes — what a caller wants when it
 * is going to write the bytes to a file — is `files/download`.
 *
 * That path has one rough edge worth handling here: it falls back to returning
 * the whole envelope (instead of zero bytes) when the resource is empty, and it
 * passes upstream error envelopes through unchanged. So a response body is
 * either raw bytes, or an envelope. An empty resource is a legitimate file and
 * must come back as a zero-byte Buffer; an envelope with code !== 0 is an error
 * and its message is surfaced verbatim.
 */

/** The bridge envelope discriminator is a numeric `code`. */
function asEnvelope(buf) {
  let parsed;
  try {
    parsed = JSON.parse(buf.toString("utf8"));
  } catch {
    return null;
  }
  if (parsed && typeof parsed === "object" && !Array.isArray(parsed) && typeof parsed.code === "number") return parsed;
  return null;
}

export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch }) {
  const base = String(bridgeBase ?? "").replace(/\/+$/, "");
  const res = await fetcher(`${base}/files/download`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });
  const bytes = Buffer.from(await res.arrayBuffer());
  const envelope = asEnvelope(bytes);
  if (!envelope) return bytes;
  if (envelope.code !== 0) {
    throw new Error(String(envelope.message ?? `skill-bridge returned code ${envelope.code} for ${skillId}:${path}`));
  }
  // code 0 with the envelope still in hand: the download path hands back the
  // envelope rather than bytes when the resource is empty. Decode it; an empty
  // string is a valid zero-byte file, not an error. A missing/non-string
  // content field is the real malformed case.
  const data = envelope.data ?? {};
  if (typeof data.content !== "string") {
    throw new Error(`skill-bridge envelope for ${skillId}:${path} has no string content`);
  }
  return Buffer.from(data.content, data.encoding === "base64" ? "base64" : "utf8");
}
